export function poolForMapBucket(bucket: MapBucket): MapQuestion[] {
  let pool = MAP_QUESTIONS.filter((q) => q.mapSlug === bucket.slug);
  if (bucket.maxDifficulty != null) {
    pool = pool.filter((q) => q.difficulty <= bucket.maxDifficulty!);
  }
  return pool;
}

export function pickAdaptiveMap(
  currentDifficulty: number,
  askedKeys: Set<string>,
  pool: MapQuestion[],
): MapQuestion | null {
  for (let d = 0; d <= 9; d++) {
    for (const offset of [0, -d, d]) {
      if (d === 0 && offset !== 0) continue;
      const target = currentDifficulty + offset;
      if (target < 1 || target > 10) continue;
      const candidates = pool.filter(
        (q) =>
          q.difficulty === target &&
          !askedKeys.has(`${q.nodeSlug}:${q.question}`),
      );
      if (candidates.length > 0) {
        return candidates[Math.floor(Math.random() * candidates.length)];
      }
    }
  }
  return null;
}
